eventos.t:
python3 - <<'EOF'
import json
R = json.load(open("avatar_ranges.json"))
R = [r for r in R if r["file"] != "avatar/A25.mp4"]
R.sort(key=lambda r: r["startMs"])
for a,b in zip(R, R[1:]):
    if b["startMs"] < a["endMs"]: print("OVERLAP", a["file"], b["file"])
for r in R: print(r["file"], r["startMs"], r["endMs"], r.get("foto",""))
print(len(R), sum(r["endMs"]-r["startMs"] for r in R)/1000)
json.dump

